//! Mip levels as 1.21.11 makes them (`MipmapGenerator`, `TextureUtil.solidify`,
//! `TextureUtil.fillEmptyAreasWithDarkColor`, `ARGB`; reimplemented, DESIGN.md §3.6). Exact to
//! Java: `f32` arithmetic in Java's order, its sRGB tables generated by the JDK, its fill order.
//!
//! Java mips a sprite's whole sheet, every frame at once, and cuts the frames from each level.

use std::collections::VecDeque;

use crate::image::Image;
use crate::sprite::{MipmapStrategy, Sprite};
use crate::srgb_tables::{LINEAR_TO_SRGB, SRGB_TO_LINEAR};

const ALPHA_CUTOFF: f32 = 0.5;
const STRICT_ALPHA_CUTOFF: f32 = 0.3;

/// The sprite's sheet at levels 0 to `levels` (0 for an atlas without mipmaps, which still gets
/// level 0's fill-in, as Java does).
pub fn levels(sprite: &Sprite, levels: u32) -> Vec<Image> {
    let mut base = sprite.sheet.clone();
    let mut strategy = sprite.mipmap_strategy;
    if strategy == MipmapStrategy::Auto {
        strategy = if has_transparent_pixel(&base) {
            MipmapStrategy::Cutout
        } else {
            MipmapStrategy::Mean
        };
    }
    let path = sprite
        .id
        .split_once(':')
        .map_or(sprite.id.as_str(), |(_, path)| path);
    if !path.starts_with("item/") {
        match strategy {
            MipmapStrategy::Cutout | MipmapStrategy::StrictCutout => solidify(&mut base),
            MipmapStrategy::DarkCutout => fill_empty_with_dark(&mut base),
            _ => {}
        }
    }
    let mut out = vec![base];
    if levels == 0 {
        return out;
    }

    let cutout = matches!(
        strategy,
        MipmapStrategy::Cutout | MipmapStrategy::StrictCutout | MipmapStrategy::DarkCutout
    );
    let cutoff = if strategy == MipmapStrategy::StrictCutout {
        STRICT_ALPHA_CUTOFF
    } else {
        ALPHA_CUTOFF
    };
    let target = if cutout {
        coverage(&out[0], cutoff, 1.0)
    } else {
        0.0
    };

    for _ in 1..=levels {
        let above = out.last().unwrap();
        let mut level = Image::new(above.width >> 1, above.height >> 1);
        for x in 0..level.width {
            for y in 0..level.height {
                let o = argb(above.texel(x * 2, y * 2));
                let p = argb(above.texel(x * 2 + 1, y * 2));
                let q = argb(above.texel(x * 2, y * 2 + 1));
                let r = argb(above.texel(x * 2 + 1, y * 2 + 1));
                let pixel = if strategy == MipmapStrategy::DarkCutout {
                    darkened_alpha_blend(o, p, q, r)
                } else {
                    mean_linear(o, p, q, r)
                };
                level.set(x, y, rgba(pixel));
            }
        }
        if cutout {
            scale_alpha_to_coverage(&mut level, target, cutoff, sprite.alpha_cutoff_bias);
        }
        out.push(level);
    }
    out
}

/// Half the size, each pixel Java's linear-light mean of a 2×2 block (`ARGB.meanLinear`): for
/// downscaling outside mipmaps, so colours don't darken.
pub fn halve_linear(image: &Image) -> Image {
    let mut out = Image::new(image.width / 2, image.height / 2);
    for x in 0..out.width {
        for y in 0..out.height {
            let pixel = mean_linear(
                argb(image.texel(x * 2, y * 2)),
                argb(image.texel(x * 2 + 1, y * 2)),
                argb(image.texel(x * 2, y * 2 + 1)),
                argb(image.texel(x * 2 + 1, y * 2 + 1)),
            );
            out.set(x, y, rgba(pixel));
        }
    }
    out
}

/// The share of the image an alpha test at `cutoff` passes, its alphas scaled by `scale`: each
/// 2×2 neighbourhood sampled bilinearly at 16 points (`alphaTestCoverage`).
fn coverage(image: &Image, cutoff: f32, scale: f32) -> f32 {
    let (width, height) = (image.width as i32, image.height as i32);
    let alpha = |x: i32, y: i32| {
        (alpha_float(argb(image.texel(x as u32, y as u32))) * scale).clamp(0.0, 1.0)
    };
    let mut total = 0.0f32;
    for y in 0..height - 1 {
        for x in 0..width - 1 {
            let (n, o, p, q) = (
                alpha(x, y),
                alpha(x + 1, y),
                alpha(x, y + 1),
                alpha(x + 1, y + 1),
            );
            let mut passing = 0.0f32;
            for s in 0..4 {
                let t = (s as f32 + 0.5) / 4.0;
                for u in 0..4 {
                    let v = (u as f32 + 0.5) / 4.0;
                    let w = n * (1.0 - v) * (1.0 - t)
                        + o * v * (1.0 - t)
                        + p * (1.0 - v) * t
                        + q * v * t;
                    if w > cutoff {
                        passing += 1.0;
                    }
                }
            }
            total += passing / 16.0;
        }
    }
    // An int product, then a float division, as Java's (a 1-pixel side divides by zero, as there).
    total / ((width - 1) * (height - 1)) as f32
}

/// Rescales alpha so the level's alpha-test coverage matches `target`: a 5-step binary search for
/// the scale, then `alpha × scale + bias + 0.025` (`scaleAlphaToCoverage`).
fn scale_alpha_to_coverage(image: &mut Image, target: f32, cutoff: f32, bias: f32) {
    let (mut low, mut high) = (0.0f32, 4.0f32);
    let mut scale = 1.0f32;
    let mut best_scale = 1.0f32;
    let mut best_error = f32::MAX;
    for _ in 0..5 {
        let covered = coverage(image, cutoff, scale);
        let error = (covered - target).abs();
        if error < best_error {
            best_error = error;
            best_scale = scale;
        }
        if covered < target {
            low = scale;
        } else if covered > target {
            high = scale;
        } else {
            break;
        }
        scale = (low + high) * 0.5;
    }
    for y in 0..image.height {
        for x in 0..image.width {
            let pixel = argb(image.texel(x, y));
            let alpha = (alpha_float(pixel) * best_scale + bias + 0.025).clamp(0.0, 1.0);
            image.set(x, y, rgba(with_alpha(alpha, pixel)));
        }
    }
}

/// Gives each fully transparent pixel the colour of the nearest opaque one (breadth first; ties
/// to whichever reached it first), keeping it transparent (`solidify`).
fn solidify(image: &mut Image) {
    let (width, height) = (image.width as i32, image.height as i32);
    let at = |x: i32, y: i32| (x + y * width) as usize;
    let mut colour = vec![0u32; (width * height) as usize];
    let mut distance = vec![i32::MAX; (width * height) as usize];
    let mut queue = VecDeque::new();
    // Java seeds column by column.
    for x in 0..width {
        for y in 0..height {
            let pixel = argb(image.texel(x as u32, y as u32));
            if pixel >> 24 != 0 {
                distance[at(x, y)] = 0;
                colour[at(x, y)] = pixel;
                queue.push_back(at(x, y));
            }
        }
    }
    while let Some(k) = queue.pop_front() {
        let (x, y) = (k as i32 % width, k as i32 / width);
        for (dx, dy) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let (nx, ny) = (x + dx, y + dy);
            if nx >= 0 && ny >= 0 && nx < width && ny < height {
                let n = at(nx, ny);
                if distance[n] > distance[k] + 1 {
                    distance[n] = distance[k] + 1;
                    colour[n] = colour[k];
                    queue.push_back(n);
                }
            }
        }
    }
    for x in 0..width {
        for y in 0..height {
            let pixel = argb(image.texel(x as u32, y as u32));
            if pixel >> 24 == 0 {
                image.set(x as u32, y as u32, rgba(colour[at(x, y)] & 0x00FF_FFFF));
            }
        }
    }
}

/// Gives every fully transparent pixel three quarters of the darkest opaque colour (the first
/// found, column by column, if several tie), keeping it transparent
/// (`fillEmptyAreasWithDarkColor`). With no opaque pixel, Java's starting value, -1, stands in.
fn fill_empty_with_dark(image: &mut Image) {
    let mut darkest = u32::MAX;
    let mut darkest_sum = i32::MAX;
    for x in 0..image.width {
        for y in 0..image.height {
            let pixel = argb(image.texel(x, y));
            if pixel >> 24 != 0 {
                let sum = channel(pixel, 16) + channel(pixel, 8) + channel(pixel, 0);
                if sum < darkest_sum {
                    darkest_sum = sum;
                    darkest = pixel;
                }
            }
        }
    }
    let dark = [16, 8, 0].map(|shift| (3 * channel(darkest, shift) / 4) as u32);
    let fill = dark[0] << 16 | dark[1] << 8 | dark[2];
    for x in 0..image.width {
        for y in 0..image.height {
            if argb(image.texel(x, y)) >> 24 == 0 {
                image.set(x, y, rgba(fill));
            }
        }
    }
}

/// `ARGB.meanLinear`: alpha averaged directly, colours in linear light through the tables.
fn mean_linear(i: u32, j: u32, k: u32, l: u32) -> u32 {
    let alpha = (channel(i, 24) + channel(j, 24) + channel(k, 24) + channel(l, 24)) / 4;
    let mean = |shift: u32| {
        let linear = [i, j, k, l].map(|p| i32::from(SRGB_TO_LINEAR[channel(p, shift) as usize]));
        u32::from(LINEAR_TO_SRGB[((linear[0] + linear[1] + linear[2] + linear[3]) / 4) as usize])
    };
    (alpha as u32) << 24 | mean(16) << 16 | mean(8) << 8 | mean(0)
}

/// `darkenedAlphaBlend`: the mean over all four, with fully transparent pixels counting as zero
/// (so edges darken), alpha included, everything through the tables.
fn darkened_alpha_blend(i: u32, j: u32, k: u32, l: u32) -> u32 {
    let mut sums = [0.0f32; 4]; // alpha, red, green, blue
    for pixel in [i, j, k, l] {
        if pixel >> 24 != 0 {
            for (sum, shift) in sums.iter_mut().zip([24, 16, 8, 0]) {
                *sum += srgb_to_linear_channel(channel(pixel, shift));
            }
        }
    }
    let [a, r, g, b] = sums.map(|sum| linear_to_srgb_channel(sum / 4.0));
    a << 24 | r << 16 | g << 8 | b
}

fn srgb_to_linear_channel(value: i32) -> f32 {
    f32::from(SRGB_TO_LINEAR[value as usize]) / 1023.0
}

fn linear_to_srgb_channel(value: f32) -> u32 {
    u32::from(LINEAR_TO_SRGB[floor(value * 1023.0) as usize])
}

fn has_transparent_pixel(image: &Image) -> bool {
    image.rgba.chunks(4).any(|p| p[3] == 0)
}

fn alpha_float(pixel: u32) -> f32 {
    (pixel >> 24) as f32 / 255.0
}

/// `ARGB.color(float alpha, int rgb)`: the alpha floored to 8 bits.
fn with_alpha(alpha: f32, pixel: u32) -> u32 {
    (floor(alpha * 255.0) as u32) << 24 | pixel & 0x00FF_FFFF
}

/// `Mth.floor` on a float.
fn floor(value: f32) -> i32 {
    let truncated = value as i32;
    if value < truncated as f32 {
        truncated - 1
    } else {
        truncated
    }
}

fn channel(pixel: u32, shift: u32) -> i32 {
    (pixel >> shift & 0xFF) as i32
}

fn argb([r, g, b, a]: [u8; 4]) -> u32 {
    u32::from_be_bytes([a, r, g, b])
}

fn rgba(argb: u32) -> [u8; 4] {
    let [a, r, g, b] = argb.to_be_bytes();
    [r, g, b, a]
}

#[cfg(test)]
mod tests {
    use super::*;

    fn image(width: u32, height: u32, pixels: &[[u8; 4]]) -> Image {
        Image {
            width,
            height,
            rgba: pixels.concat(),
        }
    }

    #[test]
    fn the_mean_is_in_linear_light() {
        // Black and white average to linear 511/1023, which is sRGB 0.735: 187, not 128.
        let mid = mean_linear(0xFF00_0000, 0xFFFF_FFFF, 0xFF00_0000, 0xFFFF_FFFF);
        assert_eq!(mid, 0xFF00_0000 | 187 << 16 | 187 << 8 | 187);
        assert_eq!(SRGB_TO_LINEAR[255], 1023);
        assert_eq!(LINEAR_TO_SRGB[(1023 / 2) as usize], 187);
    }

    #[test]
    fn solidify_fills_from_the_nearest_opaque_pixel() {
        // An opaque red pixel at the left, blue at the right, transparent between.
        let red = [255, 0, 0, 255];
        let blue = [0, 0, 255, 255];
        let clear = [0, 0, 0, 0];
        let mut img = image(5, 1, &[red, clear, clear, clear, blue]);
        solidify(&mut img);
        assert_eq!(img.texel(1, 0), [255, 0, 0, 0]);
        assert_eq!(img.texel(3, 0), [0, 0, 255, 0]);
        // The middle is equally far: red was seeded first (leftmost column), so it reached it first.
        assert_eq!(img.texel(2, 0), [255, 0, 0, 0]);
        assert_eq!(img.texel(0, 0), red);
    }

    #[test]
    fn dark_fill_uses_three_quarters_of_the_darkest() {
        let mut img = image(
            3,
            1,
            &[[200, 200, 200, 255], [40, 80, 120, 255], [0, 0, 0, 0]],
        );
        fill_empty_with_dark(&mut img);
        assert_eq!(img.texel(2, 0), [30, 60, 90, 0]);
    }

    #[test]
    fn opaque_coverage_is_full_and_empty_is_none() {
        let opaque = image(2, 2, &[[0, 0, 0, 255]; 4]);
        assert_eq!(coverage(&opaque, ALPHA_CUTOFF, 1.0), 1.0);
        let empty = image(2, 2, &[[0, 0, 0, 0]; 4]);
        assert_eq!(coverage(&empty, ALPHA_CUTOFF, 1.0), 0.0);
    }

    #[test]
    fn levels_halve_down_to_one_pixel() {
        let sprite = Sprite::still(
            "minecraft:block/x".into(),
            image(4, 4, &[[100, 150, 200, 255]; 16]),
        );
        let levels = levels(&sprite, 2);
        let sizes: Vec<(u32, u32)> = levels.iter().map(|l| (l.width, l.height)).collect();
        assert_eq!(sizes, [(4, 4), (2, 2), (1, 1)]);
        // A flat colour stays itself through linear averaging.
        assert_eq!(levels[2].texel(0, 0), [100, 150, 200, 255]);
    }

    #[test]
    fn cutout_keeps_its_coverage_at_lower_levels() {
        // A checkerboard of opaque and clear pixels: half covered at level 0.
        let pixels: Vec<[u8; 4]> = (0..64)
            .map(|i| {
                if (i % 8 + i / 8) % 2 == 0 {
                    [50, 160, 50, 255]
                } else {
                    [0, 0, 0, 0]
                }
            })
            .collect();
        let sprite = Sprite::still("minecraft:block/leaves".into(), image(8, 8, &pixels));
        let levels = levels(&sprite, 1);
        // Plain averaging would leave every level-1 pixel at alpha 127, under the 0.5 cutoff, so
        // the leaves would vanish at a distance; Java's rescaling brings them back over it.
        assert!(
            levels[1]
                .rgba
                .chunks(4)
                .all(|p| p[3] as f32 / 255.0 > ALPHA_CUTOFF)
        );
    }
}
